from datetime import date; from decimal import Decimal; from uuid import uuid4; from src.extraction.orm.layer3 import ManagedPosition, PositionStatus; from src.ledger import Account, AccountType
class TestAssetsDepreciationCoverageBoost:
    async def test_depreciation_straight_line(self, client, db, test_user): account = Account(user_id=test_user.id, name='Boost Fixed Assets', type=AccountType.ASSET, currency='USD'); db.add(account); await db.flush(); position = ManagedPosition(user_id=test_user.id, account_id=account.id, asset_identifier='BOOST_EQUIP', quantity=Decimal('1.0'), cost_basis=Decimal('10000.00'), acquisition_date=date(2024, 1, 1), status=PositionStatus.ACTIVE, currency='USD'); db.add(position); await db.commit(); await db.refresh(position); response = await client.get(f'/assets/positions/{position.id}/depreciation', params={'method': 'straight-line', 'useful_life_years': 5, 'salvage_value': '100.00'}); assert response.status_code == 200; data = response.json(); assert data['position_id'] == str(position.id); assert data['method'] == 'straight-line'
    async def test_depreciation_not_found(self, client): response = await client.get(f'/assets/positions/{uuid4()}/depreciation', params={'method': 'straight-line', 'useful_life_years': 5}); assert response.status_code == 400
